import 'dart:io';import 'package:flutter/material.dart';import '../../core/runtime/legacy/legacy_runtime_request.dart';
Future<Object?>showLegacyWindowXml(BuildContext context,LegacyRuntimeRequest request){final controls=_mapList(request.params['controls']);return showDialog<Object?>(context:context,barrierDismissible:false,builder:(d)=>Dialog.fullscreen(child:Scaffold(appBar:AppBar(title:Text(request.params['title']?.toString()??'Addon'),actions:[IconButton(onPressed:()=>Navigator.pop(d,const {'action':'close'}),icon:const Icon(Icons.close))]),body:ListView(padding:const EdgeInsets.all(24),children:[for(final c in controls)_control(d,c)])))).then((v)=>v??const {'action':'close'});}
Widget _control(BuildContext d,Map<String,Object?> c){final id=(c['id'] as num?)?.toInt()??-1,type=c['type']?.toString()??'',label=c['label']?.toString()??'';void click()=>Navigator.pop(d,{'action':'click','control_id':id});switch(type){case'button':case'radiobutton':return Padding(padding:const EdgeInsets.all(6),child:FilledButton.tonal(onPressed:click,child:Text(label)));case'label':case'textbox':return Padding(padding:const EdgeInsets.all(8),child:Text(label));case'image':final src=c['texture']?.toString()??'';return src.startsWith('http')?Image.network(src,errorBuilder:(_,__,___)=>const SizedBox.shrink()):File(src).existsSync()?Image.file(File(src)):const SizedBox.shrink();default:return ListTile(title:Text(label.isEmpty?type:label),onTap:click);}}
List<Map<String,Object?>>_mapList(Object? v)=>v is List?[for(final x in v)if(x is Map)Map<String,Object?>.from(x)]:const [];
